package com.nigson.experience.lead;

import com.nigson.experience.platform.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.*;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import static org.assertj.core.api.Assertions.*;

class QuoteLeadPersistenceTest {
 private JdbcTemplate jdbc;private QuoteLeadAssociation service;private StatefulQuoteSkuEligibilityMock commerce;private PlatformStore store;private DataSourceTransactionManager manager;private final Clock clock=Clock.systemUTC();private final UUID party=UUID.randomUUID(),market=UUID.randomUUID(),sku=UUID.randomUUID();
 private PrivateWorkload.Proof proof(String api,UUID who,String scope){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow();ActorAssertion.Actor actor=who==null?null:new ActorAssertion.Actor(who,"https://identity.synthetic.invalid","quote-customer",null,Set.of("CUSTOMER"),Set.of(scope),null);return new PrivateWorkload.Proof(route.client(),"synthetic-workload",route,actor);}
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"lead acceptance requires isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime");jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();store=new PlatformStore(jdbc,manager,clock,metrics);commerce=new StatefulQuoteSkuEligibilityMock();commerce.allow(sku,2);service=new QuoteLeadAssociation(jdbc,store,new AuditWriter(jdbc,clock,metrics),clock,commerce,"synthetic-quote-review");}
 private QuoteLeadValues.Request request(String quantity){return new QuoteLeadValues.Request(market,null,List.of(new QuoteLeadValues.Product(sku,new java.math.BigDecimal(quantity))),"Synthetic quote request","Please quote the listed item.",new QuoteLeadValues.Contact("Synthetic Buyer","buyer@example.invalid","+2348031234567"));}
 private PrivateWorkload.Proof customer(){return proof("API-088",party,"lead.quote.create_WITH_SIGNED_CUSTOMER");}
 @Test void quoteIntakePersistsOwnerRowsOutboxAuditAndStableReplayWithoutMailDependency(){String key=UUID.randomUUID().toString();var created=service.create(customer(),request("2.00"),key,UUID.randomUUID());assertThat(created.state()).isEqualTo("NEW");assertThat(service.create(customer(),request("2.00"),key,UUID.randomUUID())).isEqualTo(created);assertThat(commerce.calls()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE id=? AND type='QUOTE' AND party_id=? AND status='NEW'",Long.class,created.leadId(),party)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead_requested_item WHERE lead_id=? AND sku_id=? AND quantity=2.00",Long.class,created.leadId(),sku)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='lead.created.v1'",Long.class,created.leadId())).isEqualTo(1);String payload=jdbc.queryForObject("SELECT payload::text FROM experience.outbox_event WHERE aggregate_id=? AND event_type='lead.created.v1'",String.class,created.leadId());assertThat(EventCodec.decode(payload).path("payload").path("recipient_group").asString()).isEqualTo("synthetic-quote-review");assertThat(payload).doesNotContain("buyer@example.invalid","Synthetic Buyer","Please quote");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE resource_id=? AND action='QUOTE_CREATE'",Long.class,created.leadId())).isEqualTo(1);}
 @Test void invalidOwnershipScopeMarketSkuAndUncertainCommerceFailBeforeWrites(){long leadsBefore=jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE party_id=? AND type='QUOTE'",Long.class,party),eventsBefore=jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE event_type='lead.created.v1'",Long.class);var wrong=proof("API-088",party,"distributor.create_WITH_SIGNED_CUSTOMER");assertThatThrownBy(()->service.create(wrong,request("1"),UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->service.create(customer(),request("1.001"),UUID.randomUUID().toString(),UUID.randomUUID())).hasMessage("QUOTE_RULE_VIOLATION");commerce.unavailable();assertThatThrownBy(()->service.create(customer(),request("1"),UUID.randomUUID().toString(),UUID.randomUUID())).hasMessage("PROVIDER_UNAVAILABLE");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE party_id=? AND type='QUOTE'",Long.class,party)).isEqualTo(leadsBefore);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE event_type='lead.created.v1'",Long.class)).isEqualTo(eventsBefore);}
 @Test void changedIdempotencyBodyConflictsAndConcurrentReplayCreatesOnlyOneAggregate()throws Exception{String key=UUID.randomUUID().toString();var first=service.create(customer(),request("1"),key,UUID.randomUUID());var changed=new QuoteLeadValues.Request(market,null,List.of(new QuoteLeadValues.Product(sku,new java.math.BigDecimal("2"))),"Changed subject","Changed message",new QuoteLeadValues.Contact("Synthetic Buyer","buyer@example.invalid",null));assertThatThrownBy(()->service.create(customer(),changed,key,UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class).hasMessage("IDEMPOTENCY_HASH_MISMATCH");String raceKey=UUID.randomUUID().toString();var gate=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(8);try{var futures=new ArrayList<Future<QuoteLeadValues.Created>>();for(int i=0;i<8;i++)futures.add(pool.submit(()->{gate.await();try{return service.create(customer(),request("1"),raceKey,UUID.randomUUID());}catch(PlatformStore.Conflict inProgress){return null;}}));gate.countDown();for(var f:futures)f.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}var replay=service.create(customer(),request("1"),raceKey,UUID.randomUUID());assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE party_id=? AND type='QUOTE'",Long.class,party)).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='lead.created.v1'",Long.class,replay.leadId())).isEqualTo(1);assertThat(first.leadId()).isNotEqualTo(replay.leadId());}
 @Test void quoteContextAndAssociationAreOwnerScopedAndImmutable(){var created=service.create(customer(),request("1"),UUID.randomUUID().toString(),UUID.randomUUID());var commerce=proof("API-130",null,null);var context=service.read(commerce,created.leadId());assertThat(context.partyId()).isEqualTo(party);assertThat(context.state()).isEqualTo("NEW");assertThatThrownBy(()->service.read(proof("API-130",null,null),UUID.randomUUID())).hasMessage("NOT_FOUND");UUID quote=UUID.randomUUID(),command=UUID.randomUUID();var input=new QuoteLeadAssociation.AssociationInput(command,quote,"DRAFT");var write=proof("API-131",null,null);assertThat(service.associate(write,created.leadId(),input,UUID.randomUUID()).acknowledged()).isTrue();assertThat(service.associate(write,created.leadId(),input,UUID.randomUUID()).acknowledged()).isTrue();assertThatThrownBy(()->service.associate(write,created.leadId(),new QuoteLeadAssociation.AssociationInput(command,UUID.randomUUID(),"DRAFT"),UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThat(jdbc.queryForObject("SELECT related_quote_id FROM experience.lead WHERE id=?",UUID.class,created.leadId())).isEqualTo(quote);}
}
